class _N:
    def __init__(self, v):
        self.val = v
        self.left = None
        self.right = None


def _build(a):
    if not a:
        return None
    root = _N(a[0])
    q = [root]
    i = 1
    for n in q:
        if i < len(a) and a[i] is not None:
            n.left = _N(a[i])
            q.append(n.left)
        i += 1
        if i < len(a) and a[i] is not None:
            n.right = _N(a[i])
            q.append(n.right)
        i += 1
    return root


def _serialize(root):
    if root is None:
        return []
    out = []
    q = [root]
    for n in q:
        if n is None:
            out.append(None)
        else:
            out.append(n.val)
            q.append(n.left)
            q.append(n.right)
    while out and out[-1] is None:
        out.pop()
    return out


def is_same_tree(p, q):
    a = _build(p)
    b = _build(q)
    stack = [(a, b)]
    while stack:
        x, y = stack.pop()
        if x is None and y is None:
            continue
        if x is None or y is None or x.val != y.val:
            return False
        stack.append((x.left, y.left))
        stack.append((x.right, y.right))
    return True

