function _build(a) {
  if (!a.length) return null;
  const root = { val: a[0], left: null, right: null };
  const q = [root];
  let i = 1;
  for (let h = 0; h < q.length; h++) {
    const n = q[h];
    if (i < a.length && a[i] !== null) {
      n.left = { val: a[i], left: null, right: null };
      q.push(n.left);
    }
    i++;
    if (i < a.length && a[i] !== null) {
      n.right = { val: a[i], left: null, right: null };
      q.push(n.right);
    }
    i++;
  }
  return root;
}

function _serialize(root) {
  if (!root) return [];
  const out = [];
  const q = [root];
  for (let h = 0; h < q.length; h++) {
    const n = q[h];
    if (n === null) {
      out.push(null);
    } else {
      out.push(n.val);
      q.push(n.left);
      q.push(n.right);
    }
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return out;
}

function isSameTree(p, q) {
  const a = _build(p);
  const b = _build(q);
  const stack = [[a, b]];
  while (stack.length) {
    const [x, y] = stack.pop();
    if (!x && !y) continue;
    if (!x || !y || x.val !== y.val) return false;
    stack.push([x.left, y.left]);
    stack.push([x.right, y.right]);
  }
  return true;
}

