from collections import deque


class _GNode:
    def __init__(self, label):
        self.label = label
        self.neighbors = []


def clone_graph(adj):
    if not adj:
        return []
    originals = [_GNode(i + 1) for i in range(len(adj))]
    for i, ns in enumerate(adj):
        for x in ns:
            originals[i].neighbors.append(originals[x - 1])
    copies = {}
    start = originals[0]
    copies[start] = _GNode(start.label)
    q = deque([start])
    while q:
        cur = q.popleft()
        for nb in cur.neighbors:
            if nb not in copies:
                copies[nb] = _GNode(nb.label)
                q.append(nb)
            copies[cur].neighbors.append(copies[nb])
    out = [None] * len(adj)
    for c in copies.values():
        out[c.label - 1] = [x.label for x in c.neighbors]
    return out

