function cloneGraph(adj) {
  if (!adj.length) return [];
  const mk = (label) => ({ label, neighbors: [] });
  const originals = adj.map((_, i) => mk(i + 1));
  adj.forEach((ns, i) => {
    for (const x of ns) originals[i].neighbors.push(originals[x - 1]);
  });
  const copies = new Map();
  const start = originals[0];
  copies.set(start, mk(start.label));
  const q = [start];
  for (let h = 0; h < q.length; h++) {
    const cur = q[h];
    for (const nb of cur.neighbors) {
      if (!copies.has(nb)) {
        copies.set(nb, mk(nb.label));
        q.push(nb);
      }
      copies.get(cur).neighbors.push(copies.get(nb));
    }
  }
  const out = new Array(adj.length);
  for (const c of copies.values()) out[c.label - 1] = c.neighbors.map((x) => x.label);
  return out;
}

