            res.append(-1.0)
            continue
        seen = {c: 1.0}
        q = deque([c])
        ans = -1.0
        while q:
            u = q.popleft()
            if u == d:
                ans = seen[u]
                break
            for w, x in graph[u].items():
                if w not in seen:
